from itertools import combinations
def normalised(result):
    """Check the shape of the answer (a list of lists), then put it in a standard order: each subset sorted, and the list of subsets sorted."""
    if not isinstance(result, list) or not all(isinstance(subset, list) for subset in result):
        raise AssertionError(f"expected a list of lists, got {result!r}"[:200])
    return sorted(sorted(subset) for subset in result)
def every_subset(values):
    """The same answer worked out another way, with itertools."""
    ordered = sorted(values)
    return sorted(list(chosen) for size in range(len(ordered) + 1) for chosen in combinations(ordered, size))
